"""Fulfilment endpoints for the warehouse."""

from __future__ import annotations

from typing import Any

from orders.controllers.http import Response, not_found, conflict, bad_request, InvalidRequest, require_non_negative_int, require_str, require_positive_int
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentController:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def handle_packing_slip(self, order_id: str) -> Response:
        order = self._orders.get(order_id)
        if order is None:
            return not_found("order")
        if order.status == "cancelled":
            return conflict(f"order {order_id} is cancelled")
        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer else ""
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            product_name = product.name if product else ""
            lines.append({
                "sku": item.sku,
                "name": product_name,
                "quantity": item.quantity,
            })
        return Response(200, {
            "order_id": order_id,
            "customer_name": customer_name,
            "lines": lines,
        })

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        stock_levels = self._stock.all_levels()
        products = []
        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < threshold:
                products.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": stock_levels.get(product.sku, 0),
                })
        products.sort(key=lambda p: (p["on_hand"], p["sku"]))
        return Response(200, {"products": products})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        product = self._catalog.get(sku)
        if product is None:
            return not_found("product")
        current_on_hand = self._stock.get(sku)
        new_on_hand = current_on_hand + quantity
        self._stock.set(sku, new_on_hand)
        return Response(200, {"sku": sku, "on_hand": new_on_hand})

